chunks = [
    'python sql python',
    'sql python java',
    'java python',
]

def map_step(chunk):
    counts = {}
    for word in chunk.split():
        counts[word] = counts.get(word, 0) + 1
    return counts

def reduce_step(partials):
    total = {}
    for part in partials:
        for word, n in part.items():
            total[word] = total.get(word, 0) + n
    return total

partials = [map_step(c) for c in chunks]        # это делают разные машины
for i, p in enumerate(partials):
    print(f"машина {i}: {p}")

print('итог:  ', reduce_step(partials))
